Translate("deDE", "hansel-heavyhands", {
	title = "Hansel Heavyhands",
	subtitle = "Vollstrecker der Thoriumbruderschaft",
	found = "Thoriumspitze, nahe der Schmiede",
	hint = [=[Sucht den riesigen Zwerg der Thoriumspitze, der immer eine Ausrede hat.]=],
	allegiance = "Thoriumbruderschaft",
