	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Hansel Heavyhands ist der {link:dwarves}Zwerg{/link}, den die {link:thorium-brotherhood}Thoriumbruderschaft{/link} schickt, wenn sie jemandem wehtun will. Für einen Zwerg ist er riesig, und er weiß es. Er würde die Arbeit gern selbst erledigen, sagt er, wären da nicht seine Leiden: Finger, die in der Hitze der Schlucht wie Würste anschwellen, Ballen auf seinen Ballen und eine Erkältung, die er dem Klima zuschreibt. Also gibt er seine Befehle an andere weiter und wartet auf ihren Bericht.]=],
		},
		{
			title = "Taten",
			text = [=[• Er will, dass die schweren Kriegsgolems, die um den Kessel stampfen, zu Schrott geschlagen werden.
• Er will, dass die großen Lavaspinnen der Hochebenen getötet werden, denn sie spucken Feuer und erschrecken die Kinder der {link:thorium-point}Thoriumspitze{/link}.
• Man hat ihm befohlen, die Incendosaurier aus den Lavabecken der {link:the-slag-pit}Schlackengrube{/link} zu vertreiben, damit die Bruderschaft ihre eigenen Kundschafter hinabschicken kann.]=],
		},
	},
	mentions = {
		{ text = "Verfluchte Wurstfinger" },
		{ text = "Feurige Bedrohung!" },
		{ text = "Incendosaurier? Irgendwassaurier trifft es eher" },
	},
	bonds = {
		{ id = "taskmaster-scrange", name = "Zuchtmeister Scrange", note = "gibt ihm Befehle" },
		{ id = "master-smith-burninate", name = "Meisterschmied Burninate", note = "gibt ihm Befehle" },
	},
})

Translate("deDE", "taskmaster-scrange", {
	title = "Zuchtmeister Scrange",
	subtitle = "Stellvertretender Zuchtmeister der Thoriumspitze",
