})

Translate("deDE", "velarok-windblade", {
	title = "Velarok Windblade",
	subtitle = "Ein Mann, der Rache geschworen hat",
	found = [=[Südlich der Thoriumspitze, neben den zerfetzten Überresten von Dunkeleisenzwergen]=],
	hint = [=[Sucht den Fremden, der südlich der Thoriumspitze zwischen den toten Dunkeleisenzwergen wartet.]=],
	allegiance = "Seine eigene Sache",
	aliases = { "Velarok", "Kalaran Windblade" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Velarok Windblade ist der Rache wegen in {link:searing-gorge}die Sengende Schlucht{/link} gekommen, so sagt er jedenfalls. Er erzählt von einem Vater, den die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} des Kessels erschlugen, und von Bitten um Gerechtigkeit, die die Magistrate von {link:stormwind-city}Stormwind{/link} nicht hören wollten. Das Königreich, sagt er bitter, tue lieber so, als gäbe es diesen Winkel der Welt nicht, als seine Soldaten hierherzuschicken. Also ist er selbst gekommen, mit keiner anderen Gesellschaft als einem tollpatschigen Knappen, und er wartet auf jemanden, der kühn genug ist, ihm beim Zuschlagen zu helfen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Velarok bietet, was die Schlucht selten bietet: einen Plan. Er will die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} nicht Klinge an Klinge bekämpfen. Er will sie zuerst blenden, indem er {link:morgan-s-vigil}die Wacht{/link}ürme niederbrennt, die den Kessel bewachen, und dann zuschlagen, bevor sie sich erholen können. Jenen, die ihm helfen, verspricht er Reichtümer jenseits ihrer Träume.]=],
		},
		{
			title = "Taten",
			text = [=[• Er erzählt seine Geschichte jedem Reisenden, der zuhören will.
• Er sammelt Flammenherzen und Golemöl für eine Fackel, die kein Element löschen kann.
• Er zerlegt die Thoriumdolche der Sklaventreiber der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link}, um den Schaft der Fackel zu schmieden.
• Er zieht die Magie aus einem Symbol des {red:ragnaros}Ragnaros{/red}, das dem {link:twilight-s-hammer}Schattenhammer{/link} abgenommen wurde, um ihre Hülle zu formen.]=],
		},
	},
	chapters = {
		{
			title = "Die Fackel der Vergeltung",
			hint = [=[Sammelt, was Velarok für seine Fackel braucht, und seht zu, wie sie entsteht.]=],
			text = [=[Die Fackel wurde aus der Schlucht selbst gemacht. Ihre Flamme stammte aus den Herzen von Feuerelementaren und dem Öl von Kriegsgolems. Ihr Schaft wurde aus dem verzauberten Thorium der eigenen Klingen der Sklaventreiber geschmiedet. Ihre Hülle wurde aus einem Götzenbild des Feuerlords gefertigt, dessen üble Magie Velarok für die Aufgabe als vollkommen erachtete. Lange beugte er sich über die Teile und hieß seinen Helfer geduldig sein. Als es vollbracht war, spürte jeder, der die Fackel hob, Wellen von Hass und Zorn durch sich hindurchgehen.]=],
		},
		{
			title = "Der Betrüger",
			hint = "Setzt die vier Türme des Kessels in Brand.",
			text = [=[Die Türme brannten, und Velaroks Knappe rief, es sei herrlich. Dann legte Velarok die Gestalt eines Mannes ab. Er war ein Drache des schwarzen Drachenschwarms, und einen ermordeten Vater hatte es nie gegeben. Er hatte nur die erste Verteidigungslinie der {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} zerstört haben wollen, und er wusste, dass kein Sterblicher der Legion der {link:blackrock-clan}Blackrock{/link} geholfen hätte, hätte man ihn offen gefragt. Er verschonte jene, die ihm gedient hatten, damit sie das Chaos der kommenden Invasion der Schlucht noch erleben könnten. Er hinterließ ihnen einen Hort von Tand und dazu die Mauserhaut eines schwarzen Drachen, die seine Verwandten in der {link:burning-steppes}Brennenden Steppe{/link}, wie er sagte, nutzen könnten, um ihr Handwerk zu stärken. Dann flog er davon, dem {link:blackrock-mountain}Blackrock{/link} entgegen.]=],
		},
	},
	mentions = {
		{ text = "Göttliche Vergeltung" },
		{ text = "Die makellose Flamme" },
		{ text = "Das Schmieden des Schafts" },
		{ text = "Die Hülle der Flamme" },
		{ text = "Die Fackel der Vergeltung" },
		{ text = "Die Fackel der Vergeltung, an ihren Träger gebunden" },
		{ text = "{link:squire-maltrake}Knappe Maltrake{/link}" },
		{ text = "Setzt sie in Brand!" },
		{ text = "Tand..." },
	},
	bonds = {
		{ id = "squire-maltrake", name = "Knappe Maltrake", note = "sein Diener" },
	},
})

Translate("deDE", "squire-maltrake", {
	title = "Knappe Maltrake",
	subtitle = "Knappe von Velarok Windblade",
	found = [=[An der Seite von Velarok Windblade, südlich der Thoriumspitze]=],
	hint = "Sprecht mit dem Knappen, der neben Velarok Windblade steht.",
	allegiance = "Sein Herr",
	aliases = { "Maltrake" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Knappe Maltrake folgt {link:velarok-windblade}Velarok Windblade{/link}, und er lebt, wie er sagt, nur, um seinem Herrn zu dienen. Velarok nennt ihn einen schwerfälligen Tölpel. Es ist Maltrake, der erklärt, wie die Fackel der Vergeltung zu gebrauchen ist: Man trägt sie in jeden der vier Wachtürme des Kessels und entzündet sie darin, sodass sie sehr lange brennen und kein Wachposten sie halten kann.]=],
		},
	},
	chapters = {
		{
			title = "Tand",
			hint = [=[Vollendet das Werk der Fackel und seht, was der Knappe überreicht.]=],
			text = [=[Auf Befehl seines Herrn legte Maltrake jenen, die die Türme entzündet hatten, eine verschlossene Truhe zu Füßen. Er hatte gefragt, was mit ihnen geschehen solle, da sie keinen weiteren Nutzen mehr hätten. Sein Herr brachte ihn zum Schweigen und ließ sie leben.]=],
		},
	},
	mentions = {
		{ text = "Knappe Maltrake" },
		{ text = "Setzt sie in Brand!" },
		{ text = "Tand..." },
	},
	bonds = {
		{ id = "velarok-windblade", name = "Velarok Windblade", note = "sein Herr" },
	},
})

Translate("deDE", "dorius-stonetender", {
	title = "Dorius Stonetender",
	subtitle = "Archäologe aus Ironforge",
	found = "Der Grund der Grimesilt-Grabungsstätte",
	hint = [=[Sucht den verwundeten Zwerg am Grund der Grabung von Grimesilt.]=],
	allegiance = "Königreich Ironforge",
	aliases = { "Dorius" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Dorius Stonetender führte eine Ausgrabungsmannschaft aus Ironforge in {link:searing-gorge}die Sengende Schlucht{/link}. Sein Bruder ist Kurator Thorius aus der Halle der Forscher. Als die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} kamen, wurde seine Mannschaft verschleppt, und Dorius blieb verwundet und blutend in der Grube bei {link:grimesilt-dig-site}Grimesilt{/link} zurück. Er fleht jeden vorbeikommenden Fremden an, ihm zu helfen, das Tor nach {link:loch-modan}Loch Modan{/link} und die Straße heim nach {link:ironforge}Ironforge{/link} zu erreichen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Dorius suchte nach den Steinen, die man Suntara nennt, Reliquien, die auch die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} begehrten. Sein Schicksal führt seinen trauernden Bruder auf einen Pfad der Rache und zieht {link:ironforge}Ironforge{/link} in die Geheimnisse des Kessels.]=],
		},
		{
			title = "Taten",
			text = [=[• Er führte eine archäologische Mannschaft aus {link:ironforge}Ironforge{/link} in die Schlucht.
• Er kennzeichnete den Kessel, damit seine Männer dort nicht für immer verloren gingen.
• Trotz seiner Wunden kämpfte er sich zum Tor des Stonewroughtpasses vor.]=],
		},
	},
	chapters = {
		{
			title = "Der versengte Brief",
			hint = [=[Helft Dorius, in Sicherheit zu gelangen, und tragt fort, was er zurücklässt.]=],
			text = [=[Dorius erreichte das Tor nicht. Ein Schuss fiel, als der Pass in Sicht kam, und er stürzte. Er hinterließ einen an den Rändern versengten Brief an seinen Bruder. Darin schrieb er, dass die Steine echt seien, dass die {link:dark-iron-dwarves}Dunkeleisenzwerge{/link} sie besäßen und dass ihr Anführer, Lathoric der Schwarze, ihre Macht nutze, um die Ausgrabungsmannschaft zu versklaven. Die Männer seien zum Kessel gebracht worden. Ihr Geist sei auf eine einzige Aufgabe verdreht worden: die Erschaffung von etwas, das {link:obsidion}Obsidion{/link} heiße. Befreit sie, bat er. Als Thorius den Brief las, weinte er, und im Namen des Lichts gelobte er, dass der letzte Wunsch seines Bruders erfüllt werde.]=],
		},
		{
			title = "Der Altar von Suntara",
			hint = [=[Steigt in die Schlackengrube hinab, auf der Suche nach den Männern von Dorius.]=],
			text = [=[Die Archäologen wurden tief in der {link:the-slag-pit}Schlackengrube{/link} gefunden, noch immer arbeitend, obwohl ihre Körper versagten. Einer von ihnen erklärte im Sterben, dass die Macht der Suntara sie dazu treiben würde, ihre Aufgabe selbst nach dem Tod zu vollenden. Nur der Altar von Suntara könne sie befreien, und ihm fehle eine Reliquie, die der {link:twilight-s-hammer}Schattenhammer{/link} in den Hügeln des Firewatchgrats verwahrte. Die Reliquie wurde den Kultisten abgenommen und auf den Altar gelegt.]=],
		},
		{
			title = "Lathoric der Schwarze",
			hint = "Seht, was der Altar von Suntara erweckt.",
			text = [=[Alles war eine Falle gewesen. Dorius war nie gestorben. Als er die Suntarasteine bei {link:grimesilt-dig-site}Grimesilt{/link} fand, durchströmte ihn die Macht des {red:ragnaros}Ragnaros{/red}, und der Feuerlord gab ihm eine neue Bestimmung und einen neuen Namen: Lathoric der Schwarze. Er hatte mit der Trauer seines Bruders gespielt, um Retter in die Schlucht zu locken, damit sie an seiner Stelle den letzten Stein vom {link:twilight-s-hammer}Schattenhammer{/link} zurückgewännen. {link:obsidion}Obsidion{/link} sei durch den Willen des Feuerlords gebaut worden, prahlte er, um die {link:orcs}Orcs{/link} der Blackrockspitze zu vernichten und ihn mit seinen Brüdern in den feurigen Tiefen zu vereinen. Dann rief er den Golem, sich zu erheben. Als Thorius die Wahrheit erfuhr, wurde sein Gesicht weiß. Sein Bruder hatte ihn und ganz {link:ironforge}Ironforge{/link} verraten, und Thorius fürchtete, dass niemand sicher sei, wenn ein so edler {link:dwarves}Zwerg{/link} so leicht umgedreht werden konnte.]=],
		},
	},
	mentions = {
		{ text = "Suntarasteine" },
		{ text = "Suntarasteine, der versengte Brief" },
		{ text = "Zwergische Gerechtigkeit" },
		{ text = "Befreit sie" },
		{ text = "Erhebe dich, {link:obsidion}Obsidion{/link}!" },
	},
	bonds = {
		{ id = "curator-thorius", name = "Kurator Thorius", note = "sein Bruder" },
		{ id = "obsidion", name = "Obsidion", note = "der Golem, den seine Männer bauen mussten" },
	},
})

Translate("deDE", "obsidion", {
	title = "Obsidion",
	subtitle = "Der Golem der Schlackengrube",
	found = "Tief in der Schlackengrube, neben dem Altar von Suntara",
	hint = [=[Wagt Euch in die tiefsten Hallen der Schlackengrube, wo die Gefangenen schuften.]=],
	allegiance = "Dunkeleisenzwerge",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Obsidion ist ein Golem aus schwarzem Stein, gewaltig und reglos, der in den Tiefen der {link:the-slag-pit}Schlackengrube{/link} neben einem uralten Altar steht. Gefangene Archäologen aus {link:ironforge}Ironforge{/link} mussten ihn bauen, und sie haben Tag und Nacht an ihm gearbeitet, ihr Geist nicht länger ihr eigener. Wozu er geschaffen wurde und wessen Befehl ihn erwecken wird, wissen nur seine Erbauer.]=],
		},
	},
	bonds = {
		{ id = "dorius-stonetender", name = "Dorius Stonetender", note = "schrieb in seinem letzten Brief von ihm" },
	},
})

Translate("deDE", "overseer-maltorius", {
	title = "Aufseher Maltorius",
	subtitle = "Verräter an der Bruderschaft",
	found = "Tief in der Schlackengrube des Kessels",
	hint = [=[Steigt in die Schlackengrube hinab, wo der Verräter der Bruderschaft befiehlt.]=],
	allegiance = "Dunkeleisenzwerge",
	aliases = { "Maltorius" },
	sections = {
		{
			title = "Zusammenfassung",
