Translate("deDE", "zamael-lunthistle", {
	title = "Zamael Lunthistle",
	subtitle = "Geist im Käfig",
	found = [=[In einem Käfig auf dem Hügel des Schattenhammers, nordwestlich des Firewatchgrats]=],
