			text = [=[Zamael Lunthistle ist der Geist eines {link:night-elves}Nachtelfen{/link}, den der {link:twilight-s-hammer}Schattenhammer{/link} in einem Käfig gefangen hält. Als junger Mann geriet er an der {link:darkshore}Dunkelküste{/link} an den Kult, wandte sich von {red:elune}Elune{/red} ab und begann, die {red:old-gods}Alten Götter{/red} anzubeten. Viele Jahre später weckte ihn eine Vision der Göttin. In seiner Reue begann er ein Gebet an Elune auf einer Tafel aus reinem Gold. Der Kult fand es, brandmarkte ihn als Gotteslästerer und ließ ihn hinrichten, bevor das Gebet vollendet war. Sein Geist kann nicht hinübergehen. Der Kult hält ihn als Warnung im Käfig.]=],
		},
	},
	chapters = {
		{
			title = "Die goldene Tafel",
			hint = "Holt Zamaels Gebet vom Kult zurück, der es an sich nahm.",
			text = [=[Zamael erwartete keine Vergebung. Er bat nur darum, dass sein Gebet bei den Götzendienern gefunden werde, die es besaßen, und zu Astarii Starseeker im {link:temple-of-the-moon}Tempel des Mondes{/link} gebracht werde. Als sie es empfing, sagte sie, eine verlorene Seele sei zu Elune zurückgekehrt.]=],
		},
	},
	mentions = {
		{ text = "Gebet an Elune" },
		{ text = "Gebet an Elune, die goldene Tafel" },
	},
})

